DO $$ DECLARE definition text; BEGIN definition:=pg_get_functiondef('private.counter_festival_artist_offer(uuid,integer,jsonb,uuid)'::regprocedure); definition:=replace(definition,'NOT (offer.artist_type=''solo'' AND offer.artist_profile_id=actor) AND NOT (offer.artist_type=''band'' AND coalesce(public.caller_can_act_for_band(offer.band_id),false))','NOT coalesce(offer.artist_type=''solo'' AND offer.artist_profile_id=actor,false) AND NOT coalesce(offer.artist_type=''band'' AND public.caller_can_act_for_band(offer.band_id),false)'); EXECUTE definition; END $$;